// Node graph "graph" exported by Oanarina Archi Tool.
// Edit the parameters and run the script (⌘↩) to rebuild the geometry.

const params = {
  number_1: 3000,
};

const graph = {"comments":[],"groups":[],"links":[{"from":2,"port":"profile","to":3},{"from":1,"port":"height","to":3},{"from":3,"port":"geometry","to":4}],"nextID":5,"nodes":[{"id":1,"kind":"number","params":{"max":12000,"min":500,"value":3000},"x":20,"y":40},{"id":2,"kind":"polygon","params":{"radius":300,"sides":8},"x":20,"y":150},{"id":3,"kind":"extrude","params":{},"x":240,"y":90},{"id":4,"kind":"array","params":{},"x":460,"y":90}]};

// Apply the parameters to the Number nodes.
const ids = {number_1: 1};
for (const k in params) { const n = graph.nodes.find(function (x) { return x.id === ids[k]; }); if (n) n.params.value = params[k]; }

const result = archi.evaluateGraph(graph);
for (const id in result.errors) console.error("node " + id + ": " + result.errors[id]);
const baked = archi.bakeGraph(graph);
console.log("Baked " + baked.length + " object(s): " + result.objects + " geometry, " + result.elements + " elements.");
